namespace {
unsigned checks=0;
void require(bool condition,const std::string& label){++checks;if(!condition){std::cerr<<"x86 tail: "<<label<<'\n';std::exit(1);}}
void okay(const Status& status,const std::string& label){require(status.ok(),label+": "+status.toString());}
template<class T>void put(std::vector<u8>& bytes,size_t offset,T value){require(offset+sizeof(value)<=bytes.size(),"bounded fixture write");std::memcpy(bytes.data()+offset,&value,sizeof(value));}
ByteView view(const std::vector<u8>& bytes){return ByteView(bytes.data(),bytes.size());}
enum class Variant {kNormal,kFrame,kSavedRestore,kBadSp,kUnknownSp,kReturnSlot,kBadSaved,kAliasWrite,kPriorCall,kBadTarget};
struct Fixture {std::vector<u8> bytes;Address jump=0,tail=0,tailOperand=0;};
Fixture fixture(Variant variant=Variant::kNormal){
    Fixture result;result.bytes.resize(0x900);auto& bytes=result.bytes;
    elf::Ehdr header{};const u8 ident[]={0x7f,'E','L','F',2,1,1};std::memcpy(header.ident,ident,sizeof(ident));header.type=elf::kEtDyn;header.machine=62;header.version=1;header.entry=0x1000;header.phoff=sizeof(header);header.phentsize=sizeof(elf::Phdr);header.phnum=2;header.ehsize=sizeof(header);header.shoff=0x700;header.shentsize=sizeof(elf::Shdr);header.shnum=4;std::memcpy(bytes.data(),&header,sizeof(header));
    elf::Phdr code{};code.type=elf::kPtLoad;code.flags=elf::kPfR|elf::kPfX;code.offset=0x200;code.vaddr=0x1000;code.filesz=code.memsz=0x200;code.align=1;
    elf::Phdr data{};data.type=elf::kPtLoad;data.flags=elf::kPfR;data.offset=0x500;data.vaddr=0x2000;data.filesz=data.memsz=12;data.align=1;std::memcpy(bytes.data()+sizeof(header),&code,sizeof(code));std::memcpy(bytes.data()+sizeof(header)+sizeof(code),&data,sizeof(data));
    elf::Shdr text{};text.type=elf::kShtProgBits;text.flags=6;text.addr=0x1000;text.offset=0x200;text.size=0x200;text.addralign=1;
    elf::Shdr symbols{};symbols.type=elf::kShtSymTab;symbols.offset=0x600;symbols.size=5*sizeof(elf::Sym);symbols.link=3;symbols.info=1;symbols.entsize=sizeof(elf::Sym);symbols.addralign=8;
    std::string names(1,'\0');unsigned ordinal=1;auto symbol=[&](const std::string& name,Address address,u64 size){elf::Sym item{};item.name=names.size();names+=name;names+='\0';item.info=0x12;item.shndx=1;item.value=address;item.size=size;std::memcpy(bytes.data()+0x600+ordinal++*sizeof(item),&item,sizeof(item));};
    symbol("tail_dispatch",0x1000,0xe0);symbol("tail_one",0x1140,5);symbol("tail_two",0x1160,5);symbol("opaque",0x1180,1);
    elf::Shdr strings{};strings.type=elf::kShtStrTab;strings.offset=0x680;strings.size=names.size();strings.addralign=1;std::memcpy(bytes.data()+0x680,names.data(),names.size());std::memcpy(bytes.data()+0x740,&text,sizeof(text));std::memcpy(bytes.data()+0x780,&symbols,sizeof(symbols));std::memcpy(bytes.data()+0x7c0,&strings,sizeof(strings));
    std::fill(bytes.begin()+0x200,bytes.begin()+0x400,0xcc);size_t at=0x200;auto emit=[&](std::initializer_list<u8> codeBytes){for(auto byte:codeBytes)bytes[at++]=byte;};
    if(variant==Variant::kFrame)emit({0x48,0x83,0xec,0x08});if(variant==Variant::kSavedRestore)emit({0x53});
    emit({0x83,0xff,0x02,0x77,0});const auto guard=at-1;emit({0x89,0xf8});const auto lea=at;emit({0x48,0x8d,0x0d,0,0,0,0});put<u32>(bytes,lea+3,static_cast<u32>(0x2000-(0x1000+lea-0x200+7)));emit({0x48,0x63,0x04,0x81,0x48,0x01,0xc8});result.jump=0x1000+at-0x200;emit({0xff,0xe0});bytes[guard]=static_cast<u8>(0x280-(guard+1));
    at=0x280;if(variant==Variant::kFrame)emit({0x48,0x83,0xc4,0x08});if(variant==Variant::kSavedRestore)emit({0x5b});emit({0xb8,0x63,0,0,0,0xc3});
    for(unsigned n=0;n<2;++n){at=0x2a0+n*0x20;emit({0x0f,0x1f,0x40,0x00,0x48,0x89,0xf7}); // patchable NOP; mov rdi,rsi
        if(variant==Variant::kFrame)emit({0x48,0x83,0xc4,0x08});
        if(variant==Variant::kSavedRestore)emit({0xbb,9,0,0,0,0x5b});
        if(n==0){if(variant==Variant::kBadSp)emit({0x48,0x83,0xec,0x08});else if(variant==Variant::kUnknownSp)emit({0x48,0x89,0xd4});else if(variant==Variant::kReturnSlot)emit({0x48,0xc7,0x04,0x24,0,0,0,0});else if(variant==Variant::kBadSaved)emit({0xbb,9,0,0,0});else if(variant==Variant::kAliasWrite)emit({0x48,0x89,0x37});else if(variant==Variant::kPriorCall){emit({0xe8,0,0,0,0});put<u32>(bytes,at-4,static_cast<u32>(0x380-at));}}
        const Address target=n==0?(variant==Variant::kBadTarget?0x3000:0x1140):0x1160;if(n==0){result.tail=0x1000+at-0x200;result.tailOperand=result.tail+1;}emit({0xe9,0,0,0,0});put<u32>(bytes,at-4,static_cast<u32>(target-(0x1000+at-0x200)));
    }
    for(unsigned n=0;n<2;++n){at=0x340+n*0x20;emit({0x48,0x8d,0x47,static_cast<u8>(n?11:7),0xc3});}bytes[0x380]=0xc3;
    for(unsigned n=0;n<3;++n)put<u32>(bytes,0x500+4*n,static_cast<u32>((n==1?Address{0x10c0}:Address{0x10a0})-0x2000));
    return result;
}
const Function& dispatcher(const CodeAnalyzer& analyzer){const auto* function=analyzer.functionAt(0x1000);require(function!=nullptr,"dispatcher discovered");return *function;}
CodeAnalyzer::Options options(){CodeAnalyzer::Options result;result.linearSweepFallback=false;return result;}
bool hasSwitch(const Function& function){return std::any_of(function.resolvedIndirectJumps.begin(),function.resolvedIndirectJumps.end(),[](const auto& jump){return !jump.switchCases.empty();});}
void machineAndIr(){
    for(auto variant:{Variant::kNormal,Variant::kFrame,Variant::kSavedRestore}){const auto input=fixture(variant);ElfImage image;okay(image.load(view(input.bytes)),"load symbol-bound tail fixture");CodeAnalyzer analyzer;okay(analyzer.analyze(image,options()),"discover verified tail exits");const auto& function=dispatcher(analyzer);
        require(!function.incomplete&&hasSwitch(function)&&function.tailCalls.size()==2,"verified local tail exits preserve complete switch coverage");
        require(function.callees==std::vector<Address>({0x1140,0x1160}),"tail targets participate in the call graph");
        require(std::any_of(function.tailCalls.begin(),function.tailCalls.end(),[&](const auto& tail){return tail.branch==input.tail&&tail.target==0x1140;}),"tail metadata binds exact branch and authoritative target");
        Lifter lifter;IrFunction ir;okay(lifter.open(Arch::kX86_64),"open tail lifter");okay(lifter.liftFunction(function,image.memory(),&ir),"lift verified terminal transfers");require(ir.verify().empty(),"tail IR verifies");
        unsigned tails=0;for(const auto& insn:ir.insns)if(insn.op==MintOp::kTailCall){++tails;require(insn.a.isConstant()&&!insn.dest.valid(),"tail transfer has a constant target and no synthetic result");for(const auto& effect:ir.insns)if(effect.address==insn.address)require(effect.op!=MintOp::kLoad&&effect.op!=MintOp::kStore&&effect.op!=MintOp::kCall&&effect.op!=MintOp::kReturn,"tail JMP never synthesizes CALL push or RET pop effects");}require(tails==2,"both proved exits use the terminal tail opcode");
        normalizeRegisterAccesses(&ir);SsaFunction ssa;okay(buildSsa(ir,&ssa),"build tail SSA");require(ssa.verify().empty(),"tail SSA verifies");for(const auto& insn:ssa.insns)if(insn.op==MintOp::kTailCall)require(insn.clobbers.empty(),"terminal tail transfer never invents caller-saved return definitions");
    }
    for(auto variant:{Variant::kBadSp,Variant::kUnknownSp,Variant::kReturnSlot,Variant::kBadSaved,Variant::kAliasWrite,Variant::kPriorCall,Variant::kBadTarget}){const auto input=fixture(variant);ElfImage image;okay(image.load(view(input.bytes)),"load unsafe tail fixture");CodeAnalyzer analyzer;okay(analyzer.analyze(image,options()),"analyze unproved tail state");const auto& function=dispatcher(analyzer);require(function.incomplete&&!hasSwitch(function),"one unproved frame/alias/call/target exit prevents complete switch publication");require(std::none_of(function.tailCalls.begin(),function.tailCalls.end(),[&](const auto& tail){return tail.branch==input.tail;}),"unsafe exit never becomes a verified tail site");}
    const auto input=fixture();ElfImage image;okay(image.load(view(input.bytes)),"load bounded tail fixture");CodeAnalyzer analyzer;auto bounded=options();bounded.maxInstructions=11;okay(analyzer.analyze(image,bounded),"partially discover tail case paths");require(dispatcher(analyzer).incomplete&&!hasSwitch(dispatcher(analyzer)),"partial case/callee discovery exports no complete switch proof");
}
class TemporaryDirectory {std::string path_;public:TemporaryDirectory(){std::string path="/private/tmp/mint-x86-tail-XXXXXX";if(::mkdtemp(path.data()))path_=path;require(!path_.empty(),"create owned temporary directory");}~TemporaryDirectory(){std::error_code error;std::filesystem::remove_all(path_,error);}std::string file(const std::string& name)const{return path_+'/'+name;}};
std::vector<u8> contents(const std::string& path){std::ifstream input(path,std::ios::binary);return {std::istreambuf_iterator<char>(input),std::istreambuf_iterator<char>()};}
void write(const std::string& path,const std::vector<u8>& bytes){std::ofstream output(path,std::ios::binary|std::ios::trunc);output.write(reinterpret_cast<const char*>(bytes.data()),bytes.size());output.close();require(!output.fail(),"write owned fixture");}
void open(Session& session,const std::string& source,const std::string& project){okay(session.openPath(source),"open tail Session");okay(session.attachProject(project),"attach tail Program");okay(session.analyze(),"analyze/restore tail Program");}
void prototypes(Session& session,bool isVoid=false){okay(session.editAnnotation(0x1000,"prototype",std::string(isVoid?"void":"uint64_t")+"(uint64_t selector, uint64_t value)"),"set authoritative dispatcher prototype");for(Address target:{Address{0x1140},Address{0x1160}})okay(session.editAnnotation(target,"prototype",std::string(isVoid?"void":"uint64_t")+"(uint64_t value)"),"set authoritative tail prototype");}
std::string snapshot(Session& session){std::ostringstream out;const auto& analyzer=session.analyzer();out<<analyzer.stats().instructions<<' '<<analyzer.stats().blocks<<' '<<analyzer.stats().edges<<' '<<analyzer.stats().incompleteFunctions<<'\n';for(const auto& insn:analyzer.code().instructions())out<<insn.address<<' '<<insn.id<<' '<<unsigned(insn.size)<<' '<<unsigned(insn.flow)<<' '<<insn.target<<'\n';for(const auto& function:analyzer.functions()){out<<"function "<<function.entry<<' '<<function.incomplete<<'\n';for(auto address:function.instructions)out<<address<<' ';out<<'\n';for(auto target:function.callees)out<<"callee "<<target<<'\n';for(auto caller:analyzer.callersOf(function.entry))out<<"caller "<<caller<<'\n';for(const auto& tail:function.tailCalls)out<<"tail "<<tail.branch<<' '<<tail.target<<'\n';for(const auto& jump:function.resolvedIndirectJumps){out<<"jump "<<jump.branch<<' '<<jump.table<<'\n';for(const auto& arm:jump.switchCases)out<<arm.value<<':'<<arm.target<<' ';out<<'\n';}out<<session.irTextFor(function.entry)<<session.decompiledCFor(function.entry)<<session.cfgTextFor(function.entry);}for(const auto& row:session.programListing(0x1000,512))out<<row.address<<' '<<row.size<<' '<<unsigned(row.flow)<<' '<<row.target<<' '<<row.text<<'\n';for(Address address:{Address{0x10a0},Address{0x10b0},Address{0x1140},Address{0x1160},Address{0x2000}})out<<session.referencesText(address);return out.str();}
std::string hex32(u32 value){std::ostringstream out;for(unsigned n=0;n<4;++n){if(n)out<<' ';out<<std::hex<<std::setw(2)<<std::setfill('0')<<((value>>(n*8))&255);}return out.str();}
void typedAndLifecycle(){
    TemporaryDirectory temporary;const auto source=temporary.file("tail.elf"),project=temporary.file("program.mint");const auto input=fixture();write(source,input.bytes);Session session;open(session,source,project);require(session.decompiledCFor(0x1000).find("op_tail_transfer")!=std::string::npos,"unknown ABI contract stays an explicit terminal transfer");prototypes(session);const auto typed=session.decompiledCFor(0x1000);require(typed.find("op_tail_transfer")==std::string::npos&&typed.find("tail_one")!=std::string::npos&&typed.find("tail_two")!=std::string::npos,"compatible authoritative scalar contracts render typed tail returns");
    for(const auto* name:{"tail_one","tail_two"}){const auto at=typed.find(name),end=typed.find(';',at);require(typed.substr(at,end-at).find("value")!=std::string::npos&&typed.substr(at,end-at).find("selector")==std::string::npos,"tail argument follows the real RSI-to-RDI assignment rather than incoming selector");}
    Lifter lifter;IrFunction ir;okay(lifter.open(Arch::kX86_64),"open typed tail lifter");okay(lifter.liftFunction(dispatcher(session.analyzer()),session.image().memory(),&ir),"lift typed tail fixture");DecompileResult decompiled;okay(decompileIr(ir,&decompiled,[&](Address address){return session.displayNameAt(address);},{},{},[&](Address address){return session.prototypeAt(address);},[&](const std::string& expression,DataTypeLayout* layout){return session.program().types().resolve(expression,layout);}),"decompile with explicit SSA tail operands");for(const auto& tail:decompiled.ssa.insns)if(tail.op==MintOp::kTailCall){require(tail.tailInputs.size()==1&&tail.tailInputs[0]<decompiled.ssa.values.size(),"typed tail arguments are real verified SSA uses");const auto& argument=decompiled.ssa.values[tail.tailInputs[0]];require(argument.def==SsaDef::kEntry&&argument.storage.offset==x86::kRsi,"tail SSA use names the forwarded entry value");}
    okay(session.defineType("Pair=struct{first:u64;second:u64}"),"define aggregate ABI negative fixture");
    for(const auto* declaration:{"uint32_t(uint64_t value)","f64(uint64_t value)","uint64_t(f64 value)","uint64_t(Pair value)","Pair(uint64_t value)","uint64_t(uint64_t value, ...)","uint64_t(uint64_t a,uint64_t b,uint64_t c,uint64_t d,uint64_t e,uint64_t f,uint64_t g)","@windows64 uint64_t(uint64_t value)"}){okay(session.editAnnotation(0x1140,"prototype",declaration),"set unsupported tail ABI contract");require(session.decompiledCFor(0x1000).find("op_tail_transfer")!=std::string::npos,"unsupported or incompatible declaration never fabricates a typed tail return");}
    prototypes(session,true);const auto voidSource=session.decompiledCFor(0x1000);require(voidSource.find("op_tail_transfer")==std::string::npos&&voidSource.find("tail_one")!=std::string::npos&&voidSource.find("return;")!=std::string::npos,"matching void contracts emit a call followed by terminal void return");prototypes(session);const auto initial=snapshot(session);unsigned serial=0;
    auto fresh=[&](const std::string& label){const auto overlay=temporary.file("oracle-"+std::to_string(serial++)+".mint");write(overlay,contents(project));Session oracle;okay(oracle.openPath(source),"open full tail oracle");okay(oracle.attachProject(overlay),"attach independent oracle Program");okay(oracle.reanalyze(),"force full tail oracle");require(snapshot(session)==snapshot(oracle),label+" matches full analysis for tail/CFG/IR/C/refs/callers");};
    okay(session.editAnnotation(input.tailOperand,"patch",hex32(static_cast<u32>(Address{0x1160}-(input.tail+5)))),"retarget verified tail exit");const auto patched=snapshot(session);require(patched!=initial&&dispatcher(session.analyzer()).callees==std::vector<Address>({0x1160}),"tail-target patch updates call graph and typed output");fresh("tail target patch");okay(session.undoEdit(false),"undo tail target");require(snapshot(session)==initial,"tail-target undo restores exact derived views");okay(session.undoEdit(true),"redo tail target");require(snapshot(session)==patched,"tail-target redo restores exact target binding");fresh("tail target redo");{Session restored;open(restored,source,project);require(restored.analysisStatusText().find("mode=restored")!=std::string::npos&&snapshot(restored)==patched,"cache reproof restores verified tail exits and typed operands");}
    okay(session.editAnnotation(0x10a0,"patch","48 83 ec 08"),"invalidate tail entry stack by replacing reserved NOP");const auto invalid=snapshot(session);require(dispatcher(session.analyzer()).incomplete&&!hasSwitch(dispatcher(session.analyzer())),"frame-invalidating patch removes previously verified switch/tail proof");fresh("invalid stack patch");okay(session.undoEdit(false),"undo invalid stack patch");require(snapshot(session)==patched,"stack undo re-proves valid tail exits");okay(session.undoEdit(true),"redo invalid stack patch");require(snapshot(session)==invalid,"stack redo retains conservative incomplete result");fresh("invalid stack redo");
}
void argumentPhiAndTampering(){
    TemporaryDirectory temporary;auto input=fixture();auto& bytes=input.bytes;
    // Case zero chooses either the forwarded value or a literal, then reaches
    // one physical RDI read at the shared terminal jump.
    const u8 choose[]={0x85,0xd2,0x74,0x0c,0x48,0x89,0xf7,0xe9,0,0,0,0};std::memcpy(bytes.data()+0x2a0,choose,sizeof(choose));put<u32>(bytes,0x2a8,0x2e0-0x2ac);
    bytes[0x2b0]=0xbf;put<u32>(bytes,0x2b1,42);bytes[0x2b5]=0xe9;put<u32>(bytes,0x2b6,0x2e0-0x2ba);bytes[0x2e0]=0xe9;put<u32>(bytes,0x2e1,0x340-0x2e5);
    elf::Sym root{};std::memcpy(&root,bytes.data()+0x600+sizeof(root),sizeof(root));root.size=0x100;std::memcpy(bytes.data()+0x600+sizeof(root),&root,sizeof(root));
    const auto source=temporary.file("phi.elf");write(source,bytes);Session session;open(session,source,temporary.file("program.mint"));prototypes(session);okay(session.editAnnotation(0x1000,"prototype","uint64_t(uint64_t selector,uint64_t value,uint64_t choose)"),"declare conditional argument input");require(!dispatcher(session.analyzer()).incomplete&&dispatcher(session.analyzer()).tailCalls.size()==2,"conditional case paths preserve verified frame and tail exits");
    Lifter lifter;IrFunction ir;okay(lifter.open(Arch::kX86_64),"open phi-tail lifter");okay(lifter.liftFunction(dispatcher(session.analyzer()),session.image().memory(),&ir),"lift phi-bound tail");
    const auto names=[&](Address address){return session.displayNameAt(address);};const auto signatures=[&](Address address){return session.prototypeAt(address);};const auto layouts=[&](const std::string& expression,DataTypeLayout* out){return session.program().types().resolve(expression,out);};
    DecompileResult result;okay(decompileIr(ir,&result,names,{},{},signatures,layouts),"decompile phi-bound arguments");bool phiInput=false;
    for(const auto& tail:result.ssa.insns)if(tail.op==MintOp::kTailCall&&tail.address==0x10e0){require(tail.tailInputs.size()==1,"joined tail has exactly its declared GP argument");const auto id=tail.tailInputs[0];require(id<result.ssa.values.size(),"joined argument references an owned SSA value");phiInput=result.ssa.values[id].def==SsaDef::kPhi;}
    require(phiInput&&result.cSource.find("op_tail_transfer")==std::string::npos,"tail parameter binding retains a real conditional SSA phi");
    auto forged=result.ssa;SsaId unrelated=kNoValue;for(SsaId id=0;id<forged.values.size();++id)if(forged.values[id].def==SsaDef::kEntry&&forged.values[id].storage==Varnode::reg(x86::kRdi,8))unrelated=id;require(unrelated!=kNoValue,"unrelated but authoritative selector value exists");
    for(auto& tail:forged.insns)if(tail.op==MintOp::kTailCall&&tail.address==0x10e0){--forged.values[tail.tailInputs[0]].uses;tail.tailInputs[0]=unrelated;++forged.values[unrelated].uses;}
    require(forged.verify().empty(),"forged physical binding remains structurally valid SSA");DecompileResult rejected;okay(decompileSsa(forged,&rejected,names,{},{},signatures,layouts),"decompile structurally valid false tail binding");require(rejected.cSource.find("op_tail_transfer")!=std::string::npos,"unrelated declared SSA input cannot replace the actual all-path physical tail argument");
}
void compiler(const std::string& path){Session session;okay(session.openPath(path),"open optimized sibling-call fixture");okay(session.analyze(),"analyze optimized sibling-call fixture");const auto* symbol=session.image().findSymbol("pic_tail_switch");require(symbol!=nullptr,"compiler tail fixture has authoritative dispatcher symbol");const auto* function=session.analyzer().functionAt(symbol->value);require(function&&!function->incomplete&&hasSwitch(*function)&&function->tailCalls.size()>=6,"real compiler switch retains complete coverage across verified tail exits");require(session.decompiledCFor(symbol->value).find("op_tail_transfer")==std::string::npos,"real DWARF scalar prototypes permit typed tail output");}
}
int main(int argc,char** argv){machineAndIr();typedAndLifecycle();argumentPhiAndTampering();for(int n=1;n<argc;++n)compiler(argv[n]);std::cout<<checks<<" x86 verified tail checks passed\n";}
